## 1. Custom Elements

```js
class ToggleSwitch extends HTMLElement {
  constructor() {
    super();
    this._on = false;
  }

  connectedCallback() {
    // Called when element is inserted into the DOM
    this.render();
    this.addEventListener('click', () => {
      this._on = !this._on;
      this.setAttribute('aria-checked', String(this._on));
      this.render();
      this.dispatchEvent(new CustomEvent('change', { detail: { on: this._on } }));
    });
  }

  render() {
    this.innerHTML = `<span>${this._on ? 'ON' : 'OFF'}</span>`;
  }
}

// Register the tag
customElements.define('toggle-switch', ToggleSwitch);
```

```html
<!-- Use like native HTML -->
<toggle-switch aria-checked="false" role="switch"></toggle-switch>
```

## 2. Shadow DOM

```js
class StyledCard extends HTMLElement {
  constructor() {
    super();
    // Scoped DOM — CSS inside won't affect outside and vice versa
    const shadow = this.attachShadow({ mode: 'open' });
    shadow.innerHTML = `
      <style>
        :host { display: block; border-radius: 8px; padding: 16px; }
        h2 { color: steelblue; }  /* won't affect h2 outside this component */
      </style>
      <h2><slot name="title">Default Title</slot></h2>
      <slot></slot>
    `;
  }
}
customElements.define('styled-card', StyledCard);
```

```html
<styled-card>
  <span slot="title">My Card</span>
  <p>Card content goes here.</p>
</styled-card>
```

