## React + Web Components

React 19 improved Web Components support — custom events and properties now work natively without wrappers. Useful for design systems that must span multiple frameworks.

## Raw API (verbose)

```js
// Open database, create object store on first run
const request = indexedDB.open('interview-prep', 1);

request.onupgradeneeded = (e) => {
  const db = e.target.result;
  const store = db.createObjectStore('questions', { keyPath: 'id' });
  store.createIndex('topic', 'topic', { unique: false });
  store.createIndex('level', 'level', { unique: false });
};

request.onsuccess = (e) => {
  const db = e.target.result;

  // Write
  const tx = db.transaction('questions', 'readwrite');
  tx.objectStore('questions').add({ id: 1, topic: 'html5', level: 1, question: 'What is alt?' });

  // Read by index
  const readTx = db.transaction('questions', 'readonly');
  const index = readTx.objectStore('questions').index('topic');
  const getReq = index.getAll('html5');
  getReq.onsuccess = () => console.log(getReq.result);
};
```

