## Modern equivalent: Web Crypto API

```js
// Generate an RSA key pair in the browser
const keyPair = await window.crypto.subtle.generateKey(
  {
    name: 'RSA-OAEP',
    modulusLength: 2048,
    publicExponent: new Uint8Array([1, 0, 1]),
    hash: 'SHA-256',
  },
  true,           // extractable
  ['encrypt', 'decrypt']
);

// Export the public key as SPKI (send to server)
const publicKeyBuffer = await window.crypto.subtle.exportKey('spki', keyPair.publicKey);
const publicKeyBase64 = btoa(String.fromCharCode(...new Uint8Array(publicKeyBuffer)));
console.log('Public key:', publicKeyBase64);

// Store the private key in IndexedDB (never send it)
await db.keys.put({ id: 'main', privateKey: keyPair.privateKey });
```

## ECDSA signing example

```js
// Generate ECDSA key pair
const signingKey = await crypto.subtle.generateKey(
  { name: 'ECDSA', namedCurve: 'P-256' },
  true,
  ['sign', 'verify']
);

// Sign data
const encoder = new TextEncoder();
const data = encoder.encode('Hello, World!');
const signature = await crypto.subtle.sign(
  { name: 'ECDSA', hash: 'SHA-256' },
  signingKey.privateKey,
  data
);

// Verify signature
const isValid = await crypto.subtle.verify(
  { name: 'ECDSA', hash: 'SHA-256' },
  signingKey.publicKey,
  signature,
  data
);
console.log('Valid signature:', isValid); // true
```

